// Ordenado por PREJUÍZO EM R$ (não %) -- um produto a -90% que quase
// não vende importa menos que um a -5% vendendo muito. Dispara todo
// dia enquanto o preço não for corrigido, sem guardar estado de "já
// avisei" (mesmo padrão dos outros alertas proativos).
const linhas = $input.all().map((i) => i.json);
if (linhas.length === 0) {
  return [];
}
const hojeLabel = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

function fmtBRL(v) {
  return (Number(v) || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

const blocos = linhas.map(
  (p, i) =>
    `${i + 1}. ${p.nome_produto} (cód. ${p.codigo_produto})\n   Margem: ${p.margem_pct}% · ${fmtBRL(p.prejuizo_estimado_30d)} perdidos em 30d (${Math.round(Number(p.quantidade_vendida_30d))} ${Math.round(Number(p.quantidade_vendida_30d)) === 1 ? 'vendido' : 'vendidos'})`
);

const prejuizoTotal = linhas.reduce((soma, p) => soma + Number(p.prejuizo_estimado_30d), 0);

const mensagem = `🔴 *Produtos vendidos abaixo do custo*\n📅 ${hojeLabel}\n\n${blocos.join('\n\n')}\n\nPrejuízo estimado total: ${fmtBRL(prejuizoTotal)} nos últimos 30 dias`;

return [{ json: { mensagem } }];
